<script setup lang="ts">
const route = useRoute()
const slug = String(route.params.slug || '')

type Article = { title:string; seo:string; eyebrow:string; intro:string; image:string; read:string; sections:{title:string; body:string; tips?:string[]}[]; next?:{slug:string;title:string} }
const articles:Record<string,Article> = {
  'balance-des-blancs': { title:'Balance des blancs : arrêter de subir les couleurs de vos photos', seo:'Comprendre la balance des blancs en photo : température, dominante jaune ou bleue, automatique et réglage manuel. Guide simple par Safia Moments de Vie.', eyebrow:'Glow Up Photo · Couleur', intro:'Votre photo était douce à l’œil, mais elle ressort orange, bleue ou verdâtre ? Ce n’est pas forcément votre retouche. La balance des blancs indique à l’appareil quelle lumière il doit considérer comme neutre.', image:'/images/galery/entrepreneur6.jpg', read:'5 min', sections:[{title:'Pourquoi les couleurs changent-elles ?',body:'Toutes les lumières n’ont pas la même température de couleur. Une ampoule chaude, un ciel couvert ou une zone d’ombre ne donnent pas la même dominante. Notre cerveau compense naturellement ; l’appareil, lui, doit interpréter la scène.'},{title:'Le mode automatique est utile… mais pas infaillible',body:'La balance des blancs automatique convient à beaucoup de situations. Elle peut cependant hésiter lorsqu’une scène contient plusieurs sources de lumière ou une dominante volontaire. Le but n’est donc pas de quitter l’automatique à tout prix, mais de savoir reconnaître quand il ne traduit plus votre intention.'},{title:'Le réflexe à retenir',body:'Avant de retoucher une image trop jaune ou trop bleue, regardez la lumière présente au moment de la prise de vue. Testez un préréglage adapté ou une température différente et comparez.',tips:['Trop jaune/orange : essayez une température plus froide.','Trop bleue : réchauffez la température.','En RAW, vous gardez davantage de latitude pour ajuster la balance des blancs ensuite.']},{title:'Ce que Safia travaille en formation',body:'L’objectif n’est pas de mémoriser une valeur magique. Safia vous apprend à observer la lumière, reconnaître une dominante et choisir un rendu cohérent avec l’ambiance que vous voulez créer.'}],next:{slug:'vitesse-obturation',title:'Vitesse : figer ou laisser filer le mouvement ?'} },
  'vitesse-obturation': { title:'Vitesse d’obturation : figer l’action ou laisser filer le mouvement ?', seo:'Vitesse d’obturation en photographie : comprendre le flou de mouvement, figer une action et choisir sa vitesse selon son intention.', eyebrow:'Glow Up Photo · Réglages', intro:'Une photo floue n’est pas toujours ratée. La vraie question est : le mouvement est-il subi ou choisi ? La vitesse d’obturation vous permet précisément de décider ce que devient le mouvement dans l’image.', image:'/images/galery/entrepreneur10.jpg', read:'6 min', sections:[{title:'Ce que contrôle réellement la vitesse',body:'La vitesse d’obturation correspond au temps pendant lequel le capteur reçoit la lumière. Une durée très courte aide à figer un mouvement ; une durée plus longue laisse le déplacement s’inscrire dans l’image.'},{title:'Pourquoi une vitesse rapide assombrit la photo',body:'En réduisant le temps d’exposition, vous laissez entrer moins de lumière. Il faut donc souvent compenser avec l’ouverture ou les ISO. C’est l’une des raisons pour lesquelles les trois paramètres du triangle d’exposition doivent être pensés ensemble.'},{title:'Ne cherchez pas une vitesse universelle',body:'Le bon réglage dépend du sujet, de sa vitesse, de votre focale, de votre stabilité et surtout du rendu souhaité.',tips:['Sujet rapide : commencez par protéger le mouvement avec une vitesse plus courte.','Sujet immobile : vous pouvez souvent ralentir davantage.','Flou volontaire : stabilisez votre appareil et utilisez le mouvement comme élément créatif.']},{title:'En formation : apprendre à décider avant de régler',body:'Safia vous aide à partir de l’intention : voulez-vous figer, suggérer le mouvement ou conserver de la lumière ? Le réglage devient alors une conséquence du résultat recherché.'}],next:{slug:'triangle-exposition',title:'Le triangle d’exposition sans prise de tête'} },
  'triangle-exposition': { title:'Triangle d’exposition : ISO, vitesse et ouverture sans prise de tête', seo:'Comprendre simplement le triangle d’exposition : ouverture, vitesse et ISO, leurs effets et comment choisir le réglage prioritaire selon la photo.', eyebrow:'Glow Up Photo · Exposition', intro:'ISO, vitesse, ouverture : trois mots qui donnent parfois l’impression qu’il faut résoudre une équation avant chaque photo. En réalité, chacun a un rôle et le plus simple est de commencer par votre intention.', image:'/images/galery/entrepreneur6.jpg', read:'7 min', sections:[{title:'Les trois réglages travaillent ensemble',body:'L’ouverture règle la quantité de lumière qui traverse l’objectif et influence la profondeur de champ. La vitesse règle la durée pendant laquelle la lumière atteint le capteur et influence le rendu du mouvement. Les ISO permettent d’adapter la luminosité du signal, avec davantage de bruit numérique lorsqu’on les pousse fortement.'},{title:'Commencez par ce qui compte pour votre image',body:'Pour un portrait avec un arrière-plan doux, l’ouverture peut être votre priorité. Pour une personne qui court, la vitesse devient souvent prioritaire. Ensuite seulement, équilibrez les autres paramètres pour obtenir l’exposition souhaitée.'},{title:'Pourquoi le mode manuel paraît compliqué',body:'Le problème vient souvent du fait qu’on essaie de régler les trois paramètres simultanément sans hiérarchie. Donnez-vous une priorité créative, puis compensez.',tips:['Mouvement important → pensez vitesse en premier.','Profondeur de champ importante → pensez ouverture en premier.','ISO → ajustez-les selon la lumière disponible et les limites acceptables de votre boîtier.']},{title:'Le déclic recherché',body:'Comprendre le triangle ne consiste pas à connaître une recette. C’est être capable d’expliquer pourquoi vous avez choisi un réglage et quel effet il produit sur votre photo.'}],next:{slug:'flou-photo',title:'Photo floue : erreur ou intention ?'} },
  'flou-photo': { title:'Photo floue : erreur technique ou intention créative ?', seo:'Pourquoi une photo est floue ? Mise au point, vitesse, mouvement, profondeur de champ : diagnostic simple pour comprendre et corriger le flou.', eyebrow:'Glow Up Photo · Netteté', intro:'« Ma photo est floue » ne suffit pas pour trouver la solution. Un flou peut venir du sujet, du photographe, de la mise au point ou d’une profondeur de champ trop faible. Le bon réflexe consiste d’abord à identifier lequel.', image:'/images/galery/entrepreneur10.jpg', read:'6 min', sections:[{title:'Flou de mouvement',body:'Si le sujet se déplace pendant une exposition trop longue, son mouvement apparaît dans l’image. Une vitesse plus courte peut aider à le figer, mais elle laisse aussi entrer moins de lumière.'},{title:'Flou de bougé',body:'Même avec un sujet immobile, le mouvement de vos mains peut réduire la netteté. La stabilité, la focale utilisée et la vitesse choisie jouent alors ensemble.'},{title:'Mise au point et profondeur de champ',body:'Une image peut également sembler ratée parce que la zone nette n’est pas placée au bon endroit ou parce qu’elle est très fine. Une grande ouverture peut créer un magnifique détachement du sujet, mais demande davantage de précision.',tips:['Zoomez sur l’image pour identifier où se trouve réellement la netteté.','Regardez la vitesse utilisée avant de conclure que l’autofocus est en cause.','Demandez-vous si le flou dessert l’image… ou s’il raconte le mouvement.']},{title:'Transformer une erreur en choix',body:'Une fois la cause comprise, le flou cesse d’être quelque chose que vous subissez. Safia peut travailler avec vous sur vos propres images pour isoler le problème et choisir la correction adaptée.'}],next:{slug:'cadrage-composition',title:'Cadrage : faire une image avec intention'} },
  'cadrage-composition': { title:'Cadrage photo : une belle image ne dépend pas que du matériel', seo:'Améliorer son cadrage et sa composition photo : intention, arrière-plan, placement du sujet et lecture de l’image.', eyebrow:'Glow Up Photo · Composition', intro:'Changer d’objectif ne corrigera pas toujours une photo qui semble vide, confuse ou sans force. Très souvent, ce qui manque est une intention claire : qu’est-ce que vous voulez que l’on regarde, ressente ou comprenne ?', image:'/images/galery/entrepreneur6.jpg', read:'5 min', sections:[{title:'Avant de déclencher, simplifiez',body:'Regardez les bords de votre cadre, l’arrière-plan et les éléments qui attirent l’œil. Un petit déplacement du photographe peut parfois améliorer davantage l’image qu’un nouveau réglage.'},{title:'Les règles sont des repères, pas des obligations',body:'Règle des tiers, lignes directrices, symétrie ou espace négatif peuvent aider à construire une image. Mais une composition devient intéressante lorsqu’elle sert votre sujet plutôt que lorsqu’elle applique mécaniquement une grille.'},{title:'Posez-vous trois questions',body:'Qui ou quoi est le sujet ? Où l’œil doit-il aller en premier ? Quel élément du cadre n’apporte rien ?',tips:['Vérifiez les quatre coins avant de déclencher.','Essayez un pas à gauche, à droite, plus bas ou plus haut.','Faites une version serrée puis une version plus large pour comparer l’histoire racontée.']},{title:'Développer son regard',body:'La composition s’apprend beaucoup par l’analyse. En accompagnement, Safia peut revenir sur vos images, montrer ce qui fonctionne déjà et identifier les choix de cadrage qui renforceraient votre intention.'}],next:{slug:'flash-photo',title:'Flash : arrêter d’en avoir peur'} },
  'flash-photo': { title:'Flash photo : arrêter d’en avoir peur et comprendre quand l’utiliser', seo:'Débuter avec le flash en photographie : comprendre son rôle, éviter le rendu agressif et apprendre à l’utiliser comme une lumière complémentaire.', eyebrow:'Glow Up Photo · Lumière', intro:'Le flash a mauvaise réputation parce qu’on pense souvent au coup de lumière frontal, dur et peu naturel. Pourtant, un flash n’est qu’une source de lumière supplémentaire : bien compris, il peut résoudre des situations que la lumière disponible ne permet pas.', image:'/images/galery/entrepreneur10.jpg', read:'6 min', sections:[{title:'Le flash n’a pas besoin de se voir',body:'Une lumière artificielle réussie n’est pas forcément spectaculaire. Selon sa direction, sa puissance et la façon dont elle est diffusée ou réfléchie, elle peut simplement redonner du relief au sujet ou équilibrer une scène.'},{title:'Pourquoi le rendu devient parfois dur',body:'Une petite source frontale proche de l’axe de l’objectif crée facilement une lumière plate et des ombres marquées. Modifier la direction ou agrandir la source apparente change fortement le résultat.'},{title:'Commencez simple',body:'Avant de multiplier les accessoires, comprenez ce que fait votre flash par rapport à la lumière ambiante.',tips:['Faites une photo sans flash pour observer la lumière existante.','Ajoutez ensuite le flash à faible contribution et comparez.','Si votre matériel le permet, testez une lumière réfléchie plutôt que directement frontale.']},{title:'L’objectif en formation',body:'Safia ne cherche pas à vous donner une configuration unique. Le but est de comprendre ce que la lumière fait au visage, au décor et à l’ambiance pour que vous puissiez ensuite adapter votre choix à la situation.'}],next:{slug:'balance-des-blancs',title:'Balance des blancs : maîtriser les couleurs'} }
}
const article = computed(() => articles[slug])
if (!article.value) throw createError({ statusCode:404, statusMessage:'Article introuvable' })
useSeoMeta({ title: () => `${article.value.title} | Safia Moments de Vie`, description: () => article.value.seo, ogTitle: () => article.value.title, ogDescription: () => article.value.seo, ogImage: () => article.value.image, robots:'index, follow' })
useHead({ link:[{ rel:'canonical', href:`https://www.safiamomentsdevie.com/conseils-photo/${slug}` }] })
</script>

<template><main v-if="article" class="article-page"><header class="article-hero"><div class="hero-copy"><NuxtLink to="/meta-formation-photo" class="back">← Formation photo</NuxtLink><span>{{ article.eyebrow }}</span><h1>{{ article.title }}</h1><p>{{ article.intro }}</p><small>{{ article.read }} de lecture · Guide pédagogique</small></div><figure><img :src="article.image" :alt="article.title"></figure></header><div class="article-layout"><aside><span>Glow Up Photo</span><p>Des explications simples pour comprendre vos réglages et photographier avec davantage d’intention.</p><NuxtLink to="/contact?projet=formation-photo">J’ai besoin d’aide →</NuxtLink></aside><article class="content"><section v-for="(section,index) in article.sections" :key="section.title"><small>0{{ index+1 }}</small><h2>{{ section.title }}</h2><p>{{ section.body }}</p><ul v-if="section.tips"><li v-for="tip in section.tips" :key="tip">{{ tip }}</li></ul></section><div class="coach"><span>À retenir</span><h2>Un réglage n’est pas une recette. C’est un choix au service de votre image.</h2><p>Si vous comprenez la théorie mais que vous bloquez encore avec vos propres photos, Safia peut partir directement de votre pratique pour identifier ce qui vous freine.</p><NuxtLink to="/contact?projet=formation-photo" class="cta">Faire analyser mon besoin →</NuxtLink></div><NuxtLink v-if="article.next" :to="`/conseils-photo/${article.next.slug}`" class="next"><span>Continuer à apprendre</span><strong>{{ article.next.title }} →</strong></NuxtLink></article></div></main></template>

