rgba(255,255,255,.68)}.cta{display:inline-flex;background:var(--accent);padding:.9rem 1.2rem;margin-top:.8rem;font-size:.58rem;letter-spacing:.12em;text-transform:uppercase}.next{display:block;background:#fff;padding:1.5rem;border:1px solid var(--cream-dark)}.next span,.next strong{display:block}.next span{font-size:.55rem;letter-spacing:.14em;text-transform:uppercase;color:var(--accent-dark);margin-bottom:.4rem}.next strong{font-size:1.4rem}@media(max-width:800px){.article-hero{grid-template-columns:1fr;padding-top:7rem}.article-hero figure{height:480px}.article-layout{grid-template-columns:1fr;padding-top:4rem}.article-layout aside{position:static}.content>section{padding-bottom:2.5rem;margin-bottom:2.5rem}}@media(max-width:480px){.article-hero{padding-left:1.2rem;padding-right:1.2rem}.article-hero figure{height:400px}h1{font-size:2.65rem}.article-layout{padding-left:1.2rem;padding-right:1.2rem}.coach{padding:1.6rem}}</style>